import type { DialogueLine } from "../../curriculum/types";
import type { AtlasDestination, AtlasExercise, Band, Mechanic } from "../types";

// EGYPT — Arabic is the official language. English is used here as the shared language
// with guides, hotel staff, dive centres, other travellers and in business: the missions
// simulate those international exchanges, not the local language.
// Original content written for Fluent30. Dates are given conservatively (approximate, BCE).

// ---------- builders ----------
type B = Band[];
const mcq = (bands: B, prompt: string, options: string[], answer: number, explain: string, fr?: string): AtlasExercise => ({ type: "mcq", prompt, options, answer, explain, fr, bands });
const fill = (bands: B, sentence: string, answers: string[], explain: string, fr?: string, hint?: string): AtlasExercise => ({ type: "fill", sentence, answers, explain, fr, hint, bands });
const listen = (bands: B, audio: string, question: string, options: string[], answer: number, explain: string): AtlasExercise => ({ type: "listen", audio, question, options, answer, explain, bands });
const reorder = (bands: B, answer: string, explain: string, fr?: string): AtlasExercise => ({ type: "reorder", words: answer.split(" "), answer, explain, fr, bands });
const tr = (bands: B, from: "fr" | "en", text: string, answers: string[], explain: string): AtlasExercise => ({ type: "translate", from, text, answers, explain, bands });
const match = (bands: B, pairs: [string, string][], explain?: string): AtlasExercise => ({ type: "match", pairs, explain, bands });
const fix = (bands: B, sentence: string, answers: string[], explain: string): AtlasExercise => ({ type: "fix", sentence, answers, explain, bands });
const dictation = (bands: B, audio: string, answers: string[], explain: string): AtlasExercise => ({ type: "dictation", audio, answers, explain, bands });
const say = (speaker: string, en: string, fr?: string): DialogueLine => ({ speaker, en, fr });
const you = (fr: string, ...choices: [string, boolean, string][]): DialogueLine => ({ speaker: "You", fr, choices: choices.map(([en, correct, why]) => ({ en, correct, why })) });
const dialogue = (bands: B, intro: string, ...lines: DialogueLine[]): AtlasExercise => ({ type: "dialogue", intro, lines, bands });
const mech = (bands: B, m: Mechanic): AtlasExercise => ({ ...m, bands });
const produce = (title: string, prompt: string, fr: string, mustInclude: string[][], minWords: number, samples: string[], tip: string): Extract<Mechanic, { type: "produce" }> => ({ type: "produce", title, prompt, fr, mustInclude, minWords, samples, tip });

